 let atEnd=session.index===last&&(fill||s.q===r.items.length-1),atStart=session.index===first&&(fill||s.q===0),canMove=!flow||flow.phase==='answer',recording=flow?.oral&&recorder?.state==='recording',saving=recordStarting||recorder?.stopping;
